<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>롯데월드타워 설계 과정 — glm-5.3</title>
<style>
:root{
  --paper:#f6f1e7; --ink:#2b2b26; --celadon:#7a9e93; --celadon-d:#4f7a6e;
  --line:#5a5a4e; --accent:#b98a3d; --bg:#efe9dc;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  font-family:"Noto Sans KR","Malgun Gothic",sans-serif;
  background:var(--bg); color:var(--ink);
  display:flex; flex-direction:column; min-height:100vh;
}
header{
  display:flex; align-items:baseline; gap:14px; flex-wrap:wrap;
  padding:12px 18px; border-bottom:2px solid var(--ink);
  background:var(--paper);
}
header h1{font-size:1.15rem; letter-spacing:.02em}
header .sub{font-size:.8rem; color:var(--line)}
.badge{
  margin-left:auto; font-size:.72rem; padding:3px 10px;
  border:1px solid var(--celadon-d); color:var(--celadon-d); border-radius:12px;
  background:#fff;
}
main{flex:1; display:flex; min-height:0}
/* left: drawings */
#drawings{
  width:44%; min-width:300px; max-width:560px; overflow-y:auto;
  padding:14px; border-right:1px solid var(--line); background:var(--paper);
}
.tabs{display:flex; flex-wrap:wrap; gap:6px; margin-bottom:10px}
.tabs button{
  font-size:.78rem; padding:5px 10px; border:1px solid var(--line);
  background:#fff; cursor:pointer; border-radius:3px; color:var(--ink);
}
.tabs button[aria-selected="true"]{background:var(--celadon); color:#fff; border-color:var(--celadon-d)}
.sheet{background:#fff; border:1px solid var(--line); padding:10px}
.sheet svg{width:100%; height:auto; display:block}
.caption{font-size:.75rem; line-height:1.55; margin-top:8px; color:var(--ink)}
.caption strong{color:var(--celadon-d)}
.note{font-size:.7rem; color:var(--line); margin-top:6px}
#linkNote{
  margin-top:12px; padding:10px; border-left:3px solid var(--celadon-d);
  background:#fff; font-size:.78rem; line-height:1.6; min-height:64px;
}
#linkNote h3{font-size:.82rem; color:var(--celadon-d); margin-bottom:4px}
/* right: 3D */
#stage3d{flex:1; display:flex; flex-direction:column; min-width:0}
#toolbar{
  display:flex; flex-wrap:wrap; gap:6px; align-items:center;
  padding:10px 12px; border-bottom:1px solid var(--line); background:var(--paper);
}
#toolbar button, #stageSel button{
  font-size:.78rem; padding:5px 11px; border:1px solid var(--line);
  background:#fff; cursor:pointer; border-radius:3px; color:var(--ink);
}
#stageSel{display:flex; flex-wrap:wrap; gap:6px; padding:10px 12px; background:var(--paper)}
#stageSel button[aria-pressed="true"]{background:var(--celadon); color:#fff; border-color:var(--celadon-d)}
#stageDesc{font-size:.75rem; padding:0 12px 8px; color:var(--line); background:var(--paper); line-height:1.5}
#view{flex:1; position:relative; min-height:320px}
#view canvas{display:block; width:100%; height:100%}
#hint{
  position:absolute; bottom:8px; left:8px; font-size:.68rem;
  background:rgba(246,241,231,.85); padding:4px 8px; border-radius:3px; color:var(--line);
}
footer{font-size:.68rem; padding:8px 18px; border-top:1px solid var(--line); color:var(--line); background:var(--paper); line-height:1.5}
@media (max-width:820px){
  main{flex-direction:column; overflow:visible}
  #drawings{width:100%; max-width:none; border-right:none; border-bottom:1px solid var(--line)}
  #view{min-height:380px}
}
@media (prefers-reduced-motion:reduce){ .sheet svg *{transition:none!important} }
</style>
