+'<path d="M120 280 L120 60 Q210 20 300 60 L300 280" fill="#eef4f0" stroke="#4f7a6e" stroke-width="2"/>'
+'<line x1="300" y1="280" x2="330" y2="280" stroke="#2b2b26"/><line x1="120" y1="280" x2="90" y2="280" stroke="#2b2b26"/>'
+'<line x1="315" y1="280" x2="315" y2="40" stroke="#b98a3d"/><line x1="311" y1="280" x2="319" y2="280"/><line x1="311" y1="40" x2="319" y2="40"/>'
