cap:"<strong>단면도</strong> — 중앙 코어의 수직 동선과 층별 테이퍼 단면을 개념적으로 보여줍니다. 실제 구조(아웃리거·벨트트러스 등)는 LERA의 검증 도면이 아닌 추정입니다.",
note:"단위: m. 부재·단면 상세는 비공개 추정입니다."}
};
var STAGES=[
{n:"0",t:"전체 보기",d:"모든 단계의 형상을 나란히 비교합니다.",link:"배치도의 타워 위치와 입면도의 전체 높이 555m에 대응하여 단계별 매스를 비교합니다."},
{n:"1",t:"1단계 — 기본 매스",d:"직선 테이퍼 원뿔대 매스. 부지 조건과 높이 555m·123층의 기본容积을 먼저 확정합니다.",link:"입면도의 555m 높이와 위로 좁아지는 기준을 가장 단순한 직선 테이퍼로 해석한 단계입니다."},
{n:"2",t:"2단계 — 도자기의 선",d:"KPF가 참고했다고 설명한 한국 도자기의 곡선을 적용해 모서리와 상부 라인을 부드럽게 다듬습니다.",link:"평면도의 둥근 사각 외곽과 입면도 상부의 Q곡선이 이 단계에서 만들어집니다."},
{n:"3",t:"3단계 — 층과 코어",d:"123층의 층선과 코어(수직 동선)를 배치하고 스카이로비 개념을 넣습니다.",link:"단면도의 코어·스카이로비(추정)와 평면도의 코어가 이 단계의 3D 형상에 대응합니다."},
{n:"4",t:"완성 모델",d:"유리 외피, 저층 피니언, 주변 매스를 포함한 완성 형상. 회전·확대/축소·시점 초기화로 관찰하세요.",link:"배치도(주변 부지 관계)·입면도(외피 라인)·단면도(코어)가 모두 합쳐진 결과입니다."}
];
/* ---------- 도면 탭 ---------- */
var sheetBox=document.getElementById("sheetBox"),linkText=document.getElementById("linkText");
function showSheet(k){
  var s=SHEETS[k];
  sheetBox.innerHTML=s.svg+'<p class="caption">'+s.cap+'</p><p class="note">'+s.note+'</p>';
  document.querySelectorAll(".tabs button").forEach(function(b){b.setAttribute("aria-selected",b.dataset.sheet===k?"true":"false");});
}
document.querySelectorAll(".tabs button").forEach(function(b){b.addEventListener("click",function(){showSheet(b.dataset.sheet);});});
showSheet("site");
/* ---------- 3D ---------- */
var view=document.getElementById("view");
var renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
view.appendChild(renderer.domElement);
var scene=new THREE.Scene();
scene.background=new THREE.Color(0xdfe8e2);
scene.add(new THREE.HemisphereLight(0xfff6e8,0x8a9a90,1.0));
var sun=new THREE.DirectionalLight(0xffffff,1.1); sun.position.set(60,90,40); scene.add(sun);
var camera=new THREE.PerspectiveCamera(45,1,0.1,2000);
var controls=new THREE.OrbitControls(camera,renderer.domElement);
controls.enableDamping=true; controls.dampingFactor=0.08;
controls.target.set(0,26,0);
var HOME={p:new THREE.Vector3(70,55,90),t:new THREE.Vector3(0,26,0)};
function goHome(){camera.position.copy(HOME.p);controls.target.copy(HOME.t);controls.update();}
goHome();
function resize(){
  var w=view.clientWidth,h=view.clientHeight;
  renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();
}
window.addEventListener("resize",resize);
/* 프로파일: t=0(지상)~1(555m). 1단위=10m */
function radiusAt(t){return 3.2-1.15*t-0.75*t*t;} /* 도자기 곡선(오목) */
function radiusLinear(t){return 3.2-1.9*t;}
var H=55.5;
function lathePts(fn,n){
  var pts=[],i;
  for(i=0;i<=n;i++){var t=i/n;pts.push(new THREE.Vector2(Math.max(0.05,fn(t)),t*H));}
  pts.push(new THREE.Vector2(0.001,H));
  return pts;
}
var matMass=new THREE.MeshLambertMaterial({color:0xcfd8d2,transparent:true,opacity:0.95});
var matGlass=new THREE.MeshPhongMaterial({color:0x9fc4b8,shininess:80,specular:0x557766,transparent:true,opacity:0.92});
var matCore=new THREE.MeshLambertMaterial({color:0xb8a880});
var matCtx=new THREE.MeshLambertMaterial({color:0xb9b2a0});
var groups={};
function mkStage1(){
  var g=new THREE.Group();
  var m=new THREE.Mesh(new THREE.LatheGeometry(lathePts(radiusLinear,10),4),matMass.clone());
  m.material.wireframe=false;g.add(m);
  g.add(new THREE.Mesh(new THREE.BoxGeometry(9,0.3,9),matCtx));
  return g;
}
function mkStage2(){
  var g=new THREE.Group();
  g.add(new THREE.Mesh(new THREE.LatheGeometry(lathePts(radiusAt,40),32),matMass.clone()));
  g.add(new THREE.Mesh(new THREE.BoxGeometry(9,0.3,9),matCtx));
  return g;
}
function mkStage3(){
  var g=mkStage2();
  var core=new THREE.Mesh(new THREE.CylinderGeometry(1.1,1.1,H,12),matCore);
  core.position.y=H/2;g.add(core);
  var i,ringMat=new THREE.LineBasicMaterial({color:0x4f7a6e});
  for(i=1;i<=12;i++){
    var t=i/12,y=t*H,r=radiusAt(t);
    var pts=[];for(var a=0;a<=32;a++){var th=a/32*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(th)*r,y,Math.sin(th)*r));}
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),ringMat));
  }
  return g;
}
function mkStage4(){
  var g=new THREE.Group();
  g.add(new THREE.Mesh(new THREE.LatheGeometry(lathePts(radiusAt,48),48),matGlass));
  var core=new THREE.Mesh(new THREE.CylinderGeometry(1.1,1.1,H,12),matCore);
  core.position.y=H/2;g.add(core);
  /* 저층 피니언 */
  var pod=new THREE.Mesh(new THREE.CylinderGeometry(5.2,5.6,4,32),matCtx);
  pod.position.y=2;g.add(pod);
  /* 수직 라인(외피 무리언 개념) */
  var lm=new THREE.LineBasicMaterial({color:0x6d8f83});
  for(var a=0;a<24;a++){
    var th=a/24*Math.PI*2,pts=[];
    for(var s=0;s<=20;s++){var t=s/20;pts.push(new THREE.Vector3(Math.cos(th)*radiusAt(t),t*H,Math.sin(th)*radiusAt(t)));}
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),lm));
  }
  /* 주변 매스 */
  var ctxs=[[-14,3,6,8,8],[14,2.5,8,5,10],[-8,2,-14,10,6],[10,2,-14,8,6]];
  ctxs.forEach(function(c){
    var b=new THREE.Mesh(new THREE.BoxGeometry(c[3],c[4],c[5]),matCtx);
